// Alice Chen - Attempt 1
const taskList = [];

function addTask() {
  const input = document.getElementById('taskInput');
  const title = input.value;
  if (title === '') return; // Simple check

  taskList.push({ id: Date.now(), title: title, completed: false });
  input.value = '';
  render();
}

function toggleTask(id) {
  const item = taskList.find(t => t.id === id);
  if (item) item.completed = !item.completed;
  render();
}

function deleteTask(id) {
  const idx = taskList.findIndex(t => t.id === id);
  if (idx !== -1) taskList.splice(idx, 1);
  render();
}

function render() {
  const container = document.getElementById('tasks');
  container.innerHTML = '';
  taskList.forEach(t => {
    const el = document.createElement('div');
    el.innerHTML = `<input type="checkbox" ${t.completed ? 'checked' : ''} onclick="toggleTask(${t.id})"> ${t.title} <button onclick="deleteTask(${t.id})">Delete</button>`;
    container.appendChild(el);
  });
  localStorage.setItem('tasks', JSON.stringify(taskList));
}

// Alice Chen - Attempt 2 (Refactored based on AI feedback)
class TaskApp {
  constructor() {
    this.tasks = this.loadSafe();
    this.filter = 'all'; // 'all' | 'active' | 'completed'
    this.input = document.getElementById('taskInput');
    this.listContainer = document.getElementById('tasks');
    this.counterEl = document.getElementById('taskCounter');
    this.errorEl = document.getElementById('taskError');

    this.bindEvents();
    this.render();
  }

  loadSafe() {
    try {
      const data = localStorage.getItem('skillproof_tasks_v2');
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.warn('Corrupt storage, resetting:', e);
      return [];
    }
  }

  save() {
    localStorage.setItem('skillproof_tasks_v2', JSON.stringify(this.tasks));
  }

  addTask(rawTitle) {
    const title = rawTitle.trim();
    if (!title) {
      this.showError('Task title cannot be empty or whitespace.');
      return false;
    }

    // Duplicate prevention (case-insensitive)
    const exists = this.tasks.some(t => t.title.toLowerCase() === title.toLowerCase());
    if (exists) {
      this.showError('A task with this name already exists.');
      return false;
    }

    this.clearError();
    const newTask = {
      id: crypto.randomUUID ? crypto.randomUUID() : 'task_' + Date.now(),
      title,
      completed: false,
      createdAt: new Date().toISOString()
    };

    this.tasks.unshift(newTask);
    this.save();
    this.render();
    return true;
  }

  toggleTask(id) {
    this.tasks = this.tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t);
    this.save();
    this.render();
  }

  deleteTask(id) {
    this.tasks = this.tasks.filter(t => t.id !== id);
    this.save();
    this.render();
  }

  setFilter(filter) {
    this.filter = filter;
    this.render();
  }

  showError(msg) {
    if (this.errorEl) {
      this.errorEl.textContent = msg;
      this.errorEl.hidden = false;
    }
  }

  clearError() {
    if (this.errorEl) {
      this.errorEl.textContent = '';
      this.errorEl.hidden = true;
    }
  }

  getFilteredTasks() {
    if (this.filter === 'active') return this.tasks.filter(t => !t.completed);
    if (this.filter === 'completed') return this.tasks.filter(t => t.completed);
    return this.tasks;
  }

  render() {
    const filtered = this.getFilteredTasks();
    this.listContainer.innerHTML = '';

    if (filtered.length === 0) {
      const empty = document.createElement('p');
      empty.className = 'text-slate-400 text-sm py-4 text-center';
      empty.textContent = this.filter === 'all' ? 'No tasks yet. Add one above!' : `No ${this.filter} tasks found.`;
      this.listContainer.appendChild(empty);
    } else {
      filtered.forEach(task => {
        const item = document.createElement('div');
        item.className = 'flex items-center justify-between p-3 border-b border-slate-100 hover:bg-slate-50';

        const left = document.createElement('label');
        left.className = 'flex items-center gap-3 cursor-pointer select-none';

        const check = document.createElement('input');
        check.type = 'checkbox';
        check.checked = task.completed;
        check.className = 'rounded text-indigo-600 focus:ring-indigo-500';
        check.addEventListener('change', () => this.toggleTask(task.id));

        const span = document.createElement('span');
        span.textContent = task.title;
        if (task.completed) span.className = 'line-through text-slate-400';

        left.appendChild(check);
        left.appendChild(span);

        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.textContent = 'Delete';
        delBtn.className = 'text-xs text-rose-500 hover:text-rose-700 px-2 py-1';
        delBtn.setAttribute('aria-label', `Delete task "${task.title}"`);
        delBtn.addEventListener('click', () => this.deleteTask(task.id));

        item.appendChild(left);
        item.appendChild(delBtn);
        this.listContainer.appendChild(item);
      });
    }

    const activeCount = this.tasks.filter(t => !t.completed).length;
    if (this.counterEl) {
      this.counterEl.textContent = `${activeCount} active item${activeCount === 1 ? '' : 's'} remaining`;
    }
  }

  bindEvents() {
    this.input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        if (this.addTask(this.input.value)) {
          this.input.value = '';
        }
      }
    });
  }
}
